import logging
from jsilib.jsonrpc.exc import ClientClosedError

from taf.fdsw.rc.interfaces.FDSW23B.swm import SoftwareManagement23B
from taf.fdsw.rc.clients.exceptions import TimeoutExceeded

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SoftwareManagement23D(SoftwareManagement23B):

    def __init__(self, client):
        super(SoftwareManagement23D, self).__init__(client)

    def software_rollback(self, sw_slot_id, timeout=10, **kwargs):
        reset_type = kwargs.get('reset_type', [])
        params = {"slotId": str(sw_slot_id)}
        if not isinstance(reset_type, (list, tuple)):  # workaround for broken interface
            params.update(resetType=reset_type)
        else:
            params.update(option=reset_type)
        try:
            self._client.send(
                method='software.rollback',
                timeout=timeout,
                parameters=params)
        except (TimeoutExceeded, ClientClosedError):
            # ClientClosedError is raised from within jsilib when response is not provided in time
            logger.info('Connection closed due to rollback operation')
        finally:
            self._client.disconnect()
